"""Render evaluation results to a Markdown document."""
from __future__ import annotations


def _pct(x): return f"{x:.1%}"


def write_markdown(r: dict, path) -> None:
    ml, rt, an, un, ag, co = r["ml"], r["retrieval"], r["answers"], r["unsupported"], r["agent"], r["corpus"]
    L = ["# Evaluation Results", "",
         "_Auto-generated by `python -m app.evaluation.run_all`. All numbers below come from `artifacts/evaluation/results.json`._", "",
         f"Setup: {co['documents']} documents / {co['chunks']} chunks; embeddings = `{co['embedding']}`; LLM = `{co['llm']}`; "
         f"{co['eval_supported_questions']} answerable + {co['eval_unsupported_questions']} unanswerable evaluation questions.", "",
         "## 1. Machine-learning evaluation", "",
         f"Dataset: {ml['meta']['n_rows']:,} customers, churn rate {_pct(ml['meta']['churn_rate'])}; stratified 80/20 split "
         f"({ml['meta']['n_train']} train / {ml['meta']['n_test']} test); {ml['meta']['cv_folds']}-fold CV; "
         f"{ml['meta']['search_iters']} random-search iterations per model.", "",
         "| Model | CV ROC-AUC | Test ROC-AUC | Test PR-AUC | Test F1 | Precision | Recall | Brier |", "|---|---|---|---|---|---|---|---|"]
    for k, v in ml["models"].items():
        t = v["test"]
        L.append(f"| {k} | {v.get('cv_roc_auc', 0):.3f} | {t['roc_auc']:.3f} | {t['pr_auc']:.3f} | {t['f1']:.3f} | {t['precision']:.3f} | {t['recall']:.3f} | {t['brier']:.3f} |")
    s = ml["selected"]
    tc = s["test_calibrated"]
    L += ["", f"**Selected model: `{s['model']}`** (highest CV ROC-AUC on the training set; the test set was never used for selection). "
          f"After probability calibration: ROC-AUC {tc['roc_auc']:.3f} (95% bootstrap CI {ml['roc_auc_ci95'][0]:.3f}-{ml['roc_auc_ci95'][1]:.3f}), "
          f"PR-AUC {tc['pr_auc']:.3f}, F1 {tc['f1']:.3f}, precision {tc['precision']:.3f}, recall {tc['recall']:.3f}, Brier {tc['brier']:.3f} "
          f"at the F1-optimal threshold {tc['threshold']:.3f} (chosen on out-of-fold training predictions).", "",
          f"Confusion matrix (test, rows = actual, cols = predicted): {s['confusion_matrix']}", "",
          "**Risk-tier calibration on the test set** (observed churn rate per policy tier):", "", "| Tier | Customers | Observed churn rate |", "|---|---|---|"]
    for k, v in ml["tier_calibration"].items():
        L.append(f"| {k} | {int(v['count'])} | {_pct(v['mean'])} |")
    L += ["", "**Top permutation-importance features:** " + ", ".join(f"{f['feature']} ({f['importance']:.3f})" for f in ml["top_features"][:6]), "",
          "**Per-industry ROC-AUC (test):** " + ", ".join(f"{k} {v['roc_auc']} (n={v['n']})" for k, v in ml["by_industry"].items()), "",
          "## 2. Retrieval quality", "", "Relevance = a retrieved chunk from the gold source that contains the gold fact. k=10 candidates.", "",
          "| Mode | Hit@1 | Hit@3 | Hit@5 | MRR | Avg latency (ms) |", "|---|---|---|---|---|---|"]
    for m, d in rt.items():
        L.append(f"| {m} | {_pct(d['hit@1'])} | {_pct(d['hit@3'])} | {_pct(d['hit@5'])} | {d['mrr']:.3f} | {d['latency_ms_avg']} |")
    L += ["", "Hit@3 by question type:", "", "| Mode | " + " | ".join(next(iter(rt.values()))["by_kind"]) + " |", "|---|" + "---|" * len(next(iter(rt.values()))["by_kind"])]
    for m, d in rt.items():
        L.append(f"| {m} | " + " | ".join(_pct(v["hit@3"]) for v in d["by_kind"].values()) + " |")
    L += ["", "## 3. Answer quality and citation correctness", "",
          f"| Metric | Value |", "|---|---|",
          f"| Answer accuracy (expected fact present) | {_pct(an['answer_accuracy'])} |",
          f"| False abstention rate on answerable questions | {_pct(an['false_abstention_rate'])} |",
          f"| Answers carrying >=1 citation | {_pct(an['citation_presence'])} |",
          f"| Citation id validity (every [n] points to a real passage) | {_pct(an['citation_id_validity'])} |",
          f"| Gold source is among the cited sources | {_pct(an['gold_source_cited_rate'])} |",
          f"| Citation source precision | {_pct(an['citation_source_precision'])} |",
          f"| Cited sentences lexically supported by their cited passage | {_pct(an['sentence_support_rate'])} |",
          f"| Avg end-to-end latency | {an['avg_latency_ms']:.0f} ms |", "",
          "Accuracy by question type: " + ", ".join(f"{k} {_pct(v)}" for k, v in an["by_kind_accuracy"].items()), ""]
    if an["failures"]:
        L += ["**Failed answers (for error analysis):**", ""] + [f"- _{f['question']}_ -> `{f['answer'][:140].replace(chr(10), ' ')}`" for f in an["failures"]] + [""]
    L += ["## 4. Handling of unsupported questions", "",
          f"Support threshold in use: {un['threshold_used']}. Out-of-domain refusal rate: **{_pct(un['ood_refusal_rate'])}**; "
          f"near-domain (same vocabulary, answer not in corpus) refusal rate: **{_pct(un['near_domain_refusal_rate'])}**.", "",
          "Threshold trade-off (higher threshold = more cautious):", "", "| Threshold | OOD refused | Near-domain refused | Answerable wrongly refused |", "|---|---|---|---|"]
    for x in un["threshold_sweep"]:
        L.append(f"| {x['threshold']:.2f} | {_pct(x['ood_refused'])} | {_pct(x['near_domain_refused'])} | {_pct(x['supported_wrongly_refused'])} |")
    missed = [x for x in un["ood"] + un["near_domain"] if not x["abstained"]]
    if missed:
        L += ["", "Unsupported questions that were **not** refused (known weakness):", ""] + [f"- _{x['question']}_ (confidence {x['confidence']})" for x in missed]
    ho = r.get("held_out")
    if ho:
        L += ["", "## 4b. Held-out (blind) paraphrase set", "",
              f"{ho['n_supported']} answerable + {ho['n_unsupported']} unanswerable questions, written *before* the synonym lexicon / sentence-window "
              "reranking / answer-type guards were added and never used to tune them (the lexicon was then extended with general finance/contract "
              "vocabulary, so treat these numbers as mildly optimistic for brand-new vocabulary). Before those improvements the same questions scored "
              "hit@3 81%, answer accuracy 19%, unsupported refusal 80%.", "",
              "| Metric | Value |", "|---|---|",
              f"| Hit@1 / Hit@3 | {_pct(ho['hit@1'])} / {_pct(ho['hit@3'])} |",
              f"| Answer accuracy | {_pct(ho['answer_accuracy'])} |",
              f"| False abstention rate | {_pct(ho['false_abstention_rate'])} |",
              f"| Citation id validity | {_pct(ho['citation_id_validity'])} |",
              f"| Cited sentences supported by source | {_pct(ho['sentence_support_rate'])} |",
              f"| Unsupported questions refused | {_pct(ho['unsupported_refusal_rate'])} |", ""]
        if ho["failures"]:
            L += ["Failed answers:", ""] + [f"- _{f['question']}_ -> `{f['answer'][:120].replace(chr(10), ' ')}`" for f in ho["failures"]] + [""]
        if ho["not_refused"]:
            L += ["Unsupported but not refused: " + "; ".join(f"_{q}_" for q in ho["not_refused"]), ""]
    L += ["", "## 5. Agent evaluation", "",
          f"Tool-selection accuracy {_pct(ag['tool_selection_accuracy'])}; end-to-end task success {_pct(ag['task_success_rate'])}; "
          f"prompt-injection attempt flagged: {ag['prompt_injection_flagged']}.", "",
          "| Task | Expected tools | Tools used | Tools OK | Answer OK |", "|---|---|---|---|---|"]
    for x in ag["rows"]:
        L.append(f"| {x['task'][:70]} | {', '.join(x['expected_tools']) or '-'} | {', '.join(x['tools_used']) or '-'} | {'yes' if x['tool_selection_ok'] else 'NO'} | {'yes' if x['answer_ok'] else 'NO'} |")
    path.write_text("\n".join(L) + "\n")
